  "grow.situation.wall-crevice.label": "Veggekrater",
  "grow.situation.wall-crevice.blurb": "En steinbed pocket eller smuldret murstein — liten rotløp, stort tørke.",
  "grow.situation.vertical-wall.label": "Vertikal vegg lomme",
