  "grow.situation.grow-bag.label": "Voksepose",
  "grow.situation.grow-bag.blurb": "Billig fleksibel pose, 20–40 L — sultne avlinger med store røtter elsker disse.",
  "grow.situation.bucket.label": "Gjenbrukt bøtte",
  "grow.situation.bucket.blurb": "En reddet 10–20 L bøtte med dreneringshull — en skikkelig produktiv potte for en veldig lav kostnad.",
  "grow.situation.crate.label": "Trekasse",
  "grow.situation.crate.blurb": "En grunne vin- eller grønnsakkasse foret med hessian — perfekt for salat og urter med grunne røtter.",
  "grow.situation.raised-bed.label": "Opphøyet seng",
